"""Shared export pipeline used by the CSV and JSON exporters."""
import csv
import io
import json

FIELDS = ("id", "name")


def _normalize(rows):
    """Yield new dicts with only FIELDS; None/missing -> '', others str().

    Consumes ``rows`` exactly once, preserves order and never mutates input.
    """
    for row in rows:
        clean = {}
        for key in FIELDS:
            value = row.get(key)
            clean[key] = "" if value is None else str(value)
        yield clean


def _to_csv(records):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(FIELDS)
    for record in records:
        writer.writerow([record[key] for key in FIELDS])
    return buffer.getvalue()


def _to_json(records):
    return json.dumps(list(records), ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {"csv": _to_csv, "json": _to_json}


def export_rows(rows, format):
    """Serialize ``rows`` to ``format`` ('csv' or 'json')."""
    try:
        serializer = _SERIALIZERS[format]
    except (KeyError, TypeError):
        raise ValueError("unsupported format") from None
    return serializer(_normalize(rows))

